window.DATA = [{"id":"PHY-001","domain":"物理学","subdomain":"粒子物理","title":"暗物质本质","description":"宇宙中约85%的物质是暗物质，但其粒子本质完全未知。不发光、不吸光，仅通过引力相互作用。","current_state":"多项直接探测实验(如XENONnT、LZ、PandaX)未发现WIMP信号；轴子探测(ADMX)仍在推进；间接探测(AMS-02)有正电子超出但未确认来源。暗物质晕的自相互作用约束日益严格。","key_directions":["WIMP直接探测：吨级液氙探测器推进","轴子搜索：微波腔实验高频段扫描","暗物质间接探测：宇宙线反物质异常","修改引力理论(TeVeS/MOND)替代解释","暗物质湮灭/衰变的伽马射线特征"],"impact":5,"difficulty":5,"timeline":"20-50年","related":["PHY-002","COS-003"],"sources":[{"text":"XENONnT Collaboration 2023","url":"https://arxiv.org/abs/2303.14729","type":"paper"},{"text":"LZ Experiment 2024","url":"https://arxiv.org/abs/2410.17036","type":"paper"},{"text":"PandaX-4T 2024","url":"https://arxiv.org/abs/2408.02381","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-002","domain":"物理学","subdomain":"粒子物理","title":"暗能量本质","description":"暗能量占宇宙总能量约68%，驱动宇宙加速膨胀，但其本质是宇宙学常数、标量场还是修改引力，仍是开放问题。","current_state":"DESI 2024年第一批数据暗示暗能量状态方程w可能随时间演化(w0wa模型)，偏离纯宇宙学常数(w=-1)，但显著性约2-3sigma，尚不足以下定论。","key_directions":["DESI/Euclid/LSST 精确测量w(z)演化","修改引力理论在宇宙学尺度的检验","暗能量与基本物理常数的关联","真空能问题(120个数量级偏差)的解决"],"impact":5,"difficulty":5,"timeline":"10-30年","related":["PHY-001","COS-003"],"sources":[{"text":"DESI 2024 DR1 Results","url":"https://arxiv.org/abs/2404.03002","type":"paper"},{"text":"Euclid Mission 2024","url":"https://www.esa.int/Science_Exploration/Space_Science/Euclid","type":"official"}],"last_updated":"2026-07"},{"id":"PHY-003","domain":"物理学","subdomain":"粒子物理","title":"超出标准模型的新物理","description":"标准模型极其成功但不完备：无法解释中微子质量、暗物质、物质-反物质不对称。寻找新物理是粒子物理的核心目标。","current_state":"LHC Run 3未发现超出标准模型的确切信号；μ子g-2实验确认与标准模型预测有偏差(4.2sigma)；B介子反常(RK/RK*)信号在2022年更新后减弱。","key_directions":["LHC高亮度阶段(HL-LHC)对新粒子的搜索","μ子g-2偏差的起源：新轻子或新规范玻色子?","电弱相变与重子生成","味物理反常的最终定论","中微子质量产生机制(跷跷板/马约拉纳)"],"impact":5,"difficulty":5,"timeline":"10-30年","related":["PHY-004","PHY-001"],"sources":[{"text":"Muon g-2 Collaboration 2023","url":"https://journals.aps.org/prl/abstract/10.1103/PhysRevLett.131.161802","type":"paper"},{"text":"LHCb 2024 Updates","url":"https://arxiv.org/abs/2404.05187","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-004","domain":"物理学","subdomain":"粒子物理","title":"中微子质量与本质","description":"中微子有质量但标准模型没有给出机制。中微子是狄拉克粒子还是马约拉纳粒子?质量等级是正常还是倒置?这些问题关乎物质-反物质不对称。","current_state":"无中微子双贝塔衰变实验(KamLAND-Zen、LEGEND)持续降低半衰期下限；T2K/NOvA对CP破坏相位有初步迹象但未定论；JUNO即将运行，有望确定质量等级。","key_directions":["无中微子双贝塔衰变：确定马约拉纳性质","中微子CP破坏相位精确测量(DUNE/Hyper-K)","中微子质量等级确定(JUNO)","惰性中微子搜索","中微子与宇宙学：Neff与暗辐射"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["PHY-003"],"sources":[{"text":"KamLAND-Zen 2023","url":"","type":"paper"},{"text":"JUNO Status 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-005","domain":"物理学","subdomain":"凝聚态物理","title":"室温超导","description":"在常温常压(或低压)下实现零电阻导电，将彻底改变能源传输、医疗成像、交通、量子计算等领域。","current_state":"LK-99事件(2023)已被否定；高压含氢材料(如LaH10、CaH6)在接近室温超导但需百万大气压；理论预测的常压室温超导材料尚未实验确认。2024年有多个高压近室温超导的复现报告。","key_directions":["高压氢化物超导体系的系统探索","常压室温超导的理论预测与材料筛选(ML辅助)","高压到常压的路径：预压材料/化学预压","非常规超导机制(铜基/铁基/镍基)","镍基超导薄膜的最新突破(2024-2025)"],"impact":5,"difficulty":5,"timeline":"10-30年","related":["PHY-006","ENG-003"],"sources":[{"text":"Nature 2024 Superconductivity Reviews","url":"https://www.nature.com/articles/s41524-024-01206-9","type":"paper"},{"text":"APS March Meeting 2025","url":"https://meetings.aps.org/Meeting/MAR25/Session/A13.1","type":"official"}],"last_updated":"2026-07"},{"id":"PHY-006","domain":"物理学","subdomain":"凝聚态物理","title":"拓扑量子物态","description":"拓扑绝缘体、拓扑超导体、外尔半金属等拓扑物态的发现与调控，为量子计算和低能耗电子学开辟新路径。","current_state":"拓扑绝缘体和拓扑半金属已被实验确认；马约拉纳零模在纳米线中的证据增强但争议仍存；分数量子霍尔态的任意子统计实验有新进展。","key_directions":["马约拉纳任意子的确凿实验证据","拓扑量子计算：非阿贝尔编织操作","高阶拓扑物态(角态/铰链态)","非厄米拓扑物态","3D拓扑材料数据库高通量筛选"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["PHY-005","INF-003"],"sources":[{"text":"Nature Physics 2024 Topology Review","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-007","domain":"物理学","subdomain":"核物理","title":"可控核聚变(磁约束)","description":"用强磁场约束高温等离子体实现氘氚聚变，是最有希望的清洁能源路径之一。","current_state":"NIF(惯性约束)2022年实现净能量增益Q>1(但仅含靶丸层面)；ITER磁约束聚变堆预计2035年氘氚运行；私营聚变公司(CFS、TAE等)加速推进紧凑型聚变装置。CFS的SPARC已开始组装。","key_directions":["ITER氘氚运行与Q>10目标","高温超导磁体聚变装置(CFS SPARC)","等离子体破裂预测与控制(AI辅助)","聚变第一壁材料与中子辐照","氚自持增殖包层设计"],"impact":5,"difficulty":5,"timeline":"15-30年","related":["PHY-008","ENG-006"],"sources":[{"text":"ITER Progress Report 2024","url":"https://www.iter.org/","type":"official"},{"text":"CFS SPARC 2025","url":"https://cfs.energy/","type":"official"}],"last_updated":"2026-07"},{"id":"PHY-008","domain":"物理学","subdomain":"核物理","title":"可控核聚变(惯性约束)","description":"用激光压缩燃料靶丸实现聚变点火，NIF已实现净增益但工程化发电还有巨大距离。","current_state":"NIF 2022年12月实现1.5倍能量增益(2.05MJ激光输入，3.15MJ聚变能输出)；后续实验多次重复点火；但激光效率(电-光转换)极低，工程Q远小于1。","key_directions":["高重复频率激光器(半导体泵浦)","靶丸批量制造与注入精度","直接驱动 vs 间接驱动路线选择","快点火与冲击点火的优化"],"impact":4,"difficulty":5,"timeline":"30-50年","related":["PHY-007"],"sources":[{"text":"LLNL NIF 2024 Results","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-009","domain":"物理学","subdomain":"引力与时空","title":"量子引力理论","description":"将广义相对论与量子力学统一的理论。引力是否需要量子化?时空是否在普朗克尺度离散?这是物理学最深层的未解问题。","current_state":"弦理论和圈量子引力仍是主要候选理论但均无实验验证；AdS/CFT对偶提供了全息原理的数学框架；量子信息与引力(ER=EPR)的联系成为热点。","key_directions":["引力波观测对量子引力效应的约束","黑洞信息悖论的量子信息解决方案","AdS/CFT在凝聚态模拟中的应用","引力退相干效应的实验探测","时空涌现理论(从量子纠缠到几何)"],"impact":5,"difficulty":5,"timeline":"30-100年","related":["PHY-010","COS-002"],"sources":[{"text":"Living Reviews in Relativity 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-010","domain":"物理学","subdomain":"引力与时空","title":"引力波天文学新窗口","description":"LIGO/Virgo/KAGRA开启引力波天文学时代后，下一代探测器将看到宇宙诞生后的第一批黑洞并合。","current_state":"LIGO O4运行中，已检测到上百个并合事件；LISA空间引力波探测器计划2035年发射；中国天琴/太极计划推进中。脉冲星计时阵列(PTA)2023年宣布探测到纳赫兹引力波背景。","key_directions":["LISA空间引力波探测器(毫赫兹频段)","爱因斯坦望远镜(ET)第三代地面探测器","宇宙微波背景B模偏振(原初引力波)","脉冲星计时阵列纳赫兹背景的源","多信使天文学：引力波+电磁+中微子"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["PHY-009","COS-001"],"sources":[{"text":"NANOGrav 2023","url":"","type":"paper"},{"text":"LISA Mission 2024","url":"","type":"official"}],"last_updated":"2026-07"},{"id":"PHY-011","domain":"物理学","subdomain":"引力与时空","title":"时间本质与时间箭头","description":"为什么时间有方向?时间是否是基本物理量还是涌现的?微观物理定律时间反演对称，但宏观世界不可逆——这个矛盾从未被彻底解决。","current_state":"封闭系统量子信息 scrambling 的时间尺度被证明有下界(快速 scrambling 界限)；时间晶体在实验中被实现；量子纠缠与时间箭头的联系有新理论进展。","key_directions":["量子纠缠与时间箭头的关系","时间晶体的物相分类","闭路量子理论与时间反演","时间在量子引力中的角色"],"impact":4,"difficulty":5,"timeline":"20-50年","related":["PHY-009"],"sources":[{"text":"Nature Physics 2024 Time Crystals","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-012","domain":"物理学","subdomain":"统一理论","title":"弦理论与M理论验证","description":"弦理论是量子引力的主要候选理论，但其在可观测能量尺度的预测几乎为零，实验验证极其困难。","current_state":"弦景观问题(String Landscape)导致多重宇宙论争；AdS/CFT对偶在数学物理中广泛应用但无实验验证；Swampland纲领对低能有效理论施加约束。","key_directions":["Swampland距离猜想的检验","弦论在数学(几何Langlands)中的验证","AdS/CFT在量子多体系统中的应用","弦论宇宙学预测(原初引力波/非高斯性)"],"impact":4,"difficulty":5,"timeline":"50-100年","related":["PHY-009","COS-005"],"sources":[{"text":"arXiv hep-th 2024","url":"","type":"preprint"}],"last_updated":"2026-07"},{"id":"PHY-013","domain":"物理学","subdomain":"统一理论","title":"万物理论(Theory of Everything)","description":"将四种基本力(引力/电磁力/强力/弱力)统一在一个框架内的终极理论。","current_state":"电弱统一已确认；大统一理论(GUT)预言质子衰变但未观测到(超-Kamiokande下限>10^34年)；弦/M理论是候选但无实验支撑。","key_directions":["质子衰变实验(Hyper-Kamiokande)","大统一理论与中微子质量的统一","弦论统一框架的可检验预测","对称性破缺与力的统一能量尺度"],"impact":5,"difficulty":5,"timeline":"50-100年","related":["PHY-003","PHY-009","PHY-012"],"sources":[{"text":"Hyper-Kamiokande Design Report","url":"https://arxiv.org/abs/2009.03849","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-014","domain":"物理学","subdomain":"凝聚态物理","title":"高温量子霍尔效应与分数量子态","description":"在高温/零磁场下实现量子霍尔效应和分数激发，对拓扑量子计算和低功耗电子学有深远影响。","current_state":"分数量子霍尔效应在魔角石墨烯等莫尔体系中被实现；分数量子反常霍尔效应(FQAH)在2023-2024年在莫尔体系中被实验确认，不需要外磁场。","key_directions":["分数量子反常霍尔效应的任意子操控","莫尔体系中的关联拓扑物态","高温量子自旋霍尔效应材料","非阿贝尔任意子的实验编织操作"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["PHY-006"],"sources":[{"text":"Nature 2024 FQAH","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"PHY-015","domain":"物理学","subdomain":"核物理","title":"原子核稳定性极限与超重元素","description":"寻找超重元素的'稳定岛'，理解核力的极限，探索元素周期表的边界。","current_state":"已合成到118号元素(Oganesson)；119号和120号元素合成尝试进行中；超重元素的化学性质开始被研究(气相色谱)。","key_directions":["119/120号元素的合成(Titan/SHIP)","稳定岛中心(Z=114/120, N=184)的验证","超重元素相对论化学","核质量精确测量(Penning trap)"],"impact":3,"difficulty":4,"timeline":"10-30年","related":["CHE-006"],"sources":[{"text":"GSI/RIKEN 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-001","domain":"生命科学","subdomain":"神经科学","title":"意识的神经基础","description":"物质如何产生主观体验(qualia)?这是哲学的'困难问题'，也是神经科学的终极挑战。","current_state":"整合信息理论(IIT)和全局工作空间理论(GWT)是主要竞争框架；脑功能连接组学进展迅速；2024年有研究声称用IIT指标区分了意识状态；麻醉机制研究为意识神经相关提供了新线索。","key_directions":["意识神经相关物(NCC)的精确定位","整合信息理论vs全局工作空间理论的实验判别","无脑回动物(如章鱼)的意识研究","脑机接口中的意识解码","麻醉药物作用机制与意识断连"],"impact":5,"difficulty":5,"timeline":"30-100年","related":["LIF-002","INF-002"],"sources":[{"text":"Nature Neuroscience 2024 Consciousness Review","url":"","type":"paper"},{"text":"IIT 4.0 2023","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10581496/","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-002","domain":"生命科学","subdomain":"神经科学","title":"全脑连接组图谱","description":"绘制完整的大脑神经元连接图谱，理解大脑信息处理的物理基础。","current_state":"果蝇全脑连接组(约14万神经元)于2024年完成；小鼠大脑皮层局部连接组已完成；人脑全尺度连接组(约860亿神经元)仍是巨大挑战，可能需要数十年。","key_directions":["小鼠全脑连接组(约7000万神经元)","人脑尺度连接组的成像与计算方法","连接组与功能的对应关系","发育过程中连接组的动态变化"],"impact":4,"difficulty":5,"timeline":"20-50年","related":["LIF-001","LIF-003"],"sources":[{"text":"FlyWire 2024","url":"","type":"paper"},{"text":"MICrONS 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-003","domain":"生命科学","subdomain":"神经科学","title":"记忆的分子机制","description":"记忆如何在物理层面被编码、存储和提取?记忆印迹(engram)的本质是什么?","current_state":"记忆印迹细胞被光遗传学标记和操控；突触可塑性(LTP/LTD)机制深入到分子层面；2024年有研究显示记忆可能编码在突触权重网络而非单个细胞。","key_directions":["记忆印迹的分子标记与操控","长期记忆的突触结构基础(树突棘重塑)","记忆泛化与遗忘的神经机制","假记忆的生成与抑制","睡眠中记忆巩固的机制"],"impact":4,"difficulty":4,"timeline":"10-30年","related":["LIF-001","LIF-002"],"sources":[{"text":"Cell 2024 Memory Engram","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-004","domain":"生命科学","subdomain":"起源与演化","title":"生命起源","description":"非生命物质如何自发组织成生命?从化学到生物的跨越是如何发生的?","current_state":"RNA世界假说仍有主流地位；碱性热液喷口理论有实验支持；2024年有研究在实验室实现了从简单前体分子到核苷酸的连续合成路径；系外行星有机分子的光谱探测提供新线索。","key_directions":["前生物化学：从简单分子到RNA/蛋白质","碱性热液喷口的能量与物质梯度","脂质囊泡的自发形成与自复制","生命起源的信息阈值(何时算'活着')","系外行星上生命起源条件的普适性"],"impact":5,"difficulty":5,"timeline":"20-50年","related":["LIF-005","COS-004"],"sources":[{"text":"Nature Chemistry 2024 Prebiotic","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-005","domain":"生命科学","subdomain":"起源与演化","title":"合成生命","description":"从非生命组分人工构建具有自我复制、代谢和进化能力的最小生命系统。","current_state":"JCVI-syn3.0最小基因组(473基因)已合成；人工细胞能实现基本代谢和自我复制；但完全自主进化的合成生命尚未实现。无细胞蛋白质表达系统日趋成熟。","key_directions":["最小自主生命系统的设计","人工细胞器与代谢网络重构","正交生物系统(非天然碱基/氨基酸)","合成生命的进化能力设计","从底向上的基因组设计自动化"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["LIF-004","LIF-008"],"sources":[{"text":"Venter Institute 2024","url":"","type":"official"},{"text":"Synthetic Biology 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-006","domain":"生命科学","subdomain":"起源与演化","title":"寒武纪大爆发机制","description":"约5.4亿年前动物多样性突然爆发，其驱动因素(环境/基因/生态)仍是演化生物学重大谜题。","current_state":"化石记录持续丰富；基因调控网络(特别是Hox基因)的进化被认为是关键；2024年新化石发现(如澄江生物群新物种)提供了更多过渡形态。","key_directions":["基因调控网络进化与形态创新","环境因素(氧气水平/海洋化学)","生态互作驱动的多样化","前寒武纪化石的重新解释"],"impact":3,"difficulty":3,"timeline":"10-30年","related":["LIF-007"],"sources":[{"text":"Science 2024 Cambrian","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-007","domain":"生命科学","subdomain":"起源与演化","title":"第六次大灭绝速度","description":"人类活动导致的物种灭绝速率远超自然背景，量化灭绝速度并预测生态系统崩溃临界点至关重要。","current_state":"IPBES 2024报告确认约100万种物种面临灭绝；两栖动物、昆虫数量下降尤为严重；生态临界点的早期预警信号在多个系统中被检测到。","key_directions":["灭绝速率的精确量化(与化石记录对比)","生态系统临界点的预测与检测","生态网络鲁棒性与级联灭绝","保护基因组学辅助濒危物种"],"impact":4,"difficulty":3,"timeline":"5-20年","related":["EAR-005"],"sources":[{"text":"IPBES 2024 Assessment","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-008","domain":"生命科学","subdomain":"分子生物学","title":"蛋白质从头设计","description":"设计自然界不存在的全新蛋白质结构和功能，从药物到催化剂到材料。","current_state":"AlphaFold2/3已能高精度预测蛋白质结构；RFdiffusion等生成式模型能从头设计功能性蛋白质；2024年有多个从头设计蛋白质进入临床试验。David Baker获2024诺贝尔化学奖。","key_directions":["酶催化活性的从头设计","结合蛋白(药物/传感器)的设计自动化","蛋白质纳米机器与分子马达","膜蛋白的从头设计","AI驱动的大规模蛋白质设计管线"],"impact":5,"difficulty":3,"timeline":"5-15年","related":["LIF-005","CHE-001"],"sources":[{"text":"Nobel Chemistry 2024","url":"https://www.nobelprize.org/uploads/2024/10/popular-chemistryprize2024-4.pdf","type":"official"},{"text":"RFdiffusion 2024","url":"https://www.nature.com/articles/s41586-023-06415-8","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-009","domain":"生命科学","subdomain":"分子生物学","title":"RNA功能图谱与RNA疗法","description":"理解非编码RNA的全面功能图谱，开发RNA疗法(mRNA/siRNA/CRISPR RNA)治疗疾病。","current_state":"mRNA疫苗技术成熟并扩展到癌症疫苗(个体化新抗原疫苗2024年进入III期)；RNA编辑(ADAR招募)技术取得突破；ENCODE计划持续扩展非编码RNA功能注释。","key_directions":["个体化mRNA癌症疫苗","RNA编辑(CRISPR-Cas13/ADAR)疗法","环状RNA药物平台","非编码RNA功能图谱","RNA靶向小分子药物"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["LIF-008","LIF-010"],"sources":[{"text":"Moderna BioNTech 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-010","domain":"生命科学","subdomain":"分子生物学","title":"表观遗传可遗传性","description":"环境因素引起的表观遗传修饰(DNA甲基化/组蛋白修饰)能否跨代遗传?这在进化论和医学中有重大意义。","current_state":"小鼠模型显示某些表观遗传标记可跨代传递2-3代；但分子机制(如何通过生殖细胞重编程屏障)仍不清楚；人类流行病学证据(如荷兰饥荒后代)存在但难以排除混淆因素。","key_directions":["跨代表观遗传的分子载体(小RNA/代谢物)","生殖细胞重编程的逃逸机制","人类跨代表观遗传的队列研究","表观遗传编辑工具(epi-editing)"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["LIF-011"],"sources":[{"text":"Nature Reviews Genetics 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-011","domain":"生命科学","subdomain":"基因组学","title":"基因编辑精准性与安全性","description":"CRISPR等基因编辑工具的脱靶效应和长期安全性是临床应用的核心障碍，尤其在生殖细胞编辑中。","current_state":"碱基编辑和引导编辑(prime editing)显著提高精度；2023-2024年Casgevy(基于CRISPR的镰刀型贫血疗法)获FDA批准；体内编辑(LNP递送)临床试验推进中。","key_directions":["超低脱靶编辑器(小型Cas/工程化)","体内递送系统(LNP/AAV靶向)","大片段DNA精确插入(整合酶/转座子)","编辑后果的全基因组评估","生殖细胞编辑的伦理框架"],"impact":5,"difficulty":4,"timeline":"5-15年","related":["LIF-012","LIF-013"],"sources":[{"text":"FDA Casgevy Approval 2023","url":"https://www.fda.gov/news-events/press-announcements/fda-approves-casgevy-first-gene-therapies-treat-patients-sickle-cell-disease","type":"official"},{"text":"Nature Biotech 2024 Prime Editing","url":"https://www.nature.com/articles/s41587-024-02266-4","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-012","domain":"生命科学","subdomain":"基因组学","title":"合成基因组与染色体合成","description":"从化学合成DNA构建完整基因组，重新设计生命的遗传蓝图。","current_state":"Sc2.0(酵母合成基因组)项目大部分完成；人类人工染色体(HAC)技术改进；合成生物学Genome Project-write(GP-write)持续推进但人基因组合成尚未实现。","key_directions":["酵母全合成基因组完成(Sc2.0)","人类人工染色体的稳定性","基因组最小化与精简设计","合成基因组的进化潜力"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["LIF-005","LIF-011"],"sources":[{"text":"Sc2.0 Consortium 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-013","domain":"生命科学","subdomain":"基因组学","title":"基因驱动与生态控制","description":"利用基因驱动技术在野外种群中传播特定基因，用于消灭媒介昆虫或保护濒危物种。","current_state":"实验室和半野外试验中基因驱动效率持续提高；但生态风险评估和治理框架远未成熟；2024年有岛屿灭鼠的基因驱动项目进入审批。","key_directions":["安全基因驱动(可逆转/局部限制)设计","生态风险评估模型","靶向疟疾蚊虫的野外试验","入侵物种控制的基因驱动应用","国际治理框架与公众参与"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["LIF-011","EAR-005"],"sources":[{"text":"Target Malaria 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-014","domain":"生命科学","subdomain":"衰老与健康","title":"衰老机制与逆转","description":"理解衰老的分子机制，能否在表观遗传层面逆转衰老?这是长寿科学的圣杯。","current_state":"表观遗传时钟(Horvath clock)广泛使用；山中因子(Yamanaka factors)部分重编程在动物模型中延长寿命；senolytics(清除衰老细胞)药物进入临床试验；但人类抗衰老干预仍无确凿临床证据。","key_directions":["部分重编程(山中因子)的安全性优化","衰老细胞清除(senolytics)临床验证","NAD+前体/雷帕霉素/mTOR通路的长期人体试验","器官特异性衰老时钟","衰老的异质性(不同组织/不同个体)"],"impact":5,"difficulty":5,"timeline":"10-30年","related":["LIF-015","LIF-016"],"sources":[{"text":"Aging Cell 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38040663/","type":"paper"},{"text":"Sinclair Lab 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38040663/","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-015","domain":"生命科学","subdomain":"衰老与健康","title":"端粒与寿命","description":"端粒缩短与衰老的关系已被确认，但端粒酶激活能否安全延长寿命仍未知。","current_state":"端粒长度作为衰老生物标志物广泛使用；基因治疗延长端粒在动物模型中有效；但端粒酶激活的致癌风险仍是障碍。","key_directions":["组织特异性端粒酶激活策略","端粒长度作为健康预测指标","端粒与干细胞耗竭的关系","短端粒综合征的基因治疗"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["LIF-014"],"sources":[{"text":"Telomere Research 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-016","domain":"生命科学","subdomain":"衰老与健康","title":"再生医学与器官再生","description":"利用干细胞和类器官技术实现受损组织/器官的再生修复，终极目标是全器官再生。","current_state":"类器官(脑/肝/肾/心脏)技术日趋成熟；iPSC分化方案优化；2024年有研究实现部分脑损伤的修复；异种嵌合体(人-猪)器官培养仍在探索。","key_directions":["功能完整的类器官(血管化/神经化)","iPSC来源的细胞治疗规模化","异种嵌合体器官培养(人细胞→动物器官)","3D生物打印的组织/器官","心脏/肝脏/大脑的再生策略"],"impact":5,"difficulty":5,"timeline":"15-30年","related":["LIF-014","LIF-017"],"sources":[{"text":"Cell Stem Cell 2024","url":"https://www.sciencedirect.com/science/article/pii/S246845112500011X","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-017","domain":"生命科学","subdomain":"衰老与健康","title":"微生物组与健康","description":"肠道微生物组对免疫、代谢、神经退行性疾病的全面影响，以及基于微生物组的疗法。","current_state":"粪菌移植(FMT)在复发性艰难梭菌感染中获批；微生物组与免疫治疗响应的关系被确认；肠脑轴机制研究深入(迷走神经/代谢物/免疫)；但因果性证据仍有限。","key_directions":["工程化益生菌(活体生物药)","微生物组与癌症免疫治疗协同","肠脑轴:微生物组与神经退行性疾病","微生物组个体化营养干预","微生物组队列研究的因果推断"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["LIF-014"],"sources":[{"text":"Nature Microbiology 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-018","domain":"生命科学","subdomain":"神经科学","title":"神经退行性疾病治疗","description":"阿尔茨海默病、帕金森病、ALS等神经退行性疾病的病因学和疾病修饰治疗。","current_state":" Lecanemab和Donanemab(抗Aβ抗体)获批证明淀粉样蛋白假说方向正确但疗效有限；α-突触核蛋白靶向治疗(帕金森)进入III期；ALS的基因治疗推进中。","key_directions":["tau蛋白靶向免疫治疗","α-突触核蛋白靶向治疗(帕金森)","早期检测：血液生物标志物","基因治疗(SOD1/C9orf72 ALS)","神经炎症调控策略"],"impact":5,"difficulty":4,"timeline":"5-15年","related":["LIF-001","LIF-003"],"sources":[{"text":"Lecanemab FDA 2023","url":"https://www.fda.gov/news-events/press-announcements/fda-converts-novel-alzheimers-disease-treatment-traditional-approval","type":"official"},{"text":"Nature Medicine 2024","url":"https://www.nature.com/articles/s41541-024-00942-9","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-019","domain":"生命科学","subdomain":"分子生物学","title":"相分离与生物分子凝聚体","description":"细胞内无膜细胞器通过液-液相分离形成的分子凝聚体，是细胞组织的新范式。","current_state":"相分离被确认在转录调控、DNA损伤修复、RNA代谢中起关键作用；2024年研究深入到凝聚体的材料性质和动态调控；与神经退行性疾病中蛋白聚集的关系受到关注。","key_directions":["凝聚体的功能与调控机制","相分离与基因转录调控","异常相分离与疾病(神经退行/癌症)","凝聚体的工程化应用","活细胞内相分离的定量成像"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["LIF-008"],"sources":[{"text":"Cell 2024 Phase Separation","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"LIF-020","domain":"生命科学","subdomain":"衰老与健康","title":"通用流感疫苗与广谱抗病毒","description":"开发针对所有流感毒株的通用疫苗，以及广谱抗病毒药物应对未来大流行。","current_state":"mRNA平台使通用流感疫苗开发加速；多个靶向HA茎部的广谱流感疫苗进入临床；CRISPR-based抗病毒策略在研究中；mRNA大流行疫苗平台技术储备完善。","key_directions":["广谱流感疫苗(HA茎部/多价)","针对RNA病毒保守靶点的广谱抗病毒","mRNA平台快速响应新发传染病","黏膜免疫疫苗(鼻喷/口服)"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["LIF-009"],"sources":[{"text":"NIH Universal Flu Vaccine 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"MAT-001","domain":"数学与计算","subdomain":"千禧年难题","title":"P vs NP","description":"计算机科学最重要的问题：每个能快速验证的问题是否也能快速求解?若P=NP，密码学和优化将彻底改变。","current_state":"普遍相信P≠NP但无证明；现有证明壁垒(如自然证明屏障)表明传统方法可能不够；量子计算对某些NP问题(如因式分解)加速但不会解决NP完全问题。","key_directions":["证明壁垒研究(自然证明/代数化)","几何复杂性理论(GCT)方法","P vs NP与量子复杂性(BQP)的关系","近似算法与硬度(UGC猜想)"],"impact":5,"difficulty":5,"timeline":"未知(可能100年+)","related":["MAT-002","MAT-004"],"sources":[{"text":"Clay Mathematics Institute","url":"https://www.claymath.org/millennium-problems/p-vs-np","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-002","domain":"数学与计算","subdomain":"千禧年难题","title":"黎曼假设","description":"黎曼ζ函数所有非平凡零点实部均为1/2?与素数分布深刻相关，是数学最重要未解问题之一。","current_state":"计算机验证了前10万亿个零点均在临界线上；但解析方法进展缓慢；2024年有若干部分结果但无突破。","key_directions":["L-函数族的广义黎曼假设","随机矩阵理论与零点统计","非交换几何途径(Connes)","Weil猜想类比与函数域上的推广"],"impact":4,"difficulty":5,"timeline":"未知","related":["MAT-001"],"sources":[{"text":"Clay Mathematics Institute","url":"https://www.claymath.org/millennium-problems/p-vs-np","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-003","domain":"数学与计算","subdomain":"千禧年难题","title":"BSD猜想","description":"椭圆曲线的有理点群与L函数在s=1处的性状之间精确关系的猜想。","current_state":"在秩0和秩1的椭圆曲线上被证明；高秩情况仍开放；2024年有新的数值证据和部分理论进展。","key_directions":["高秩椭圆曲线的BSD验证","与Langlands纲领的联系","Iwasawa理论途径"],"impact":3,"difficulty":5,"timeline":"未知","related":["MAT-002"],"sources":[{"text":"Clay Mathematics Institute","url":"https://www.claymath.org/millennium-problems/p-vs-np","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-004","domain":"数学与计算","subdomain":"千禧年难题","title":"Navier-Stokes存在性与光滑性","description":"三维Navier-Stokes方程是否始终存在光滑解?关乎流体力学和湍流的基本理论。","current_state":"二维问题已解决；三维问题进展缓慢；2024年有新的部分正则性结果但离完全解决尚远。湍流的数学理论仍是开放领域。","key_directions":["有限时间爆破的反例构造","部分正则性与奇异集结构","湍流的数学理论(Kolmogorov理论严格化)","数值模拟对爆破行为的线索"],"impact":3,"difficulty":5,"timeline":"未知","related":[],"sources":[{"text":"Clay Mathematics Institute","url":"https://www.claymath.org/millennium-problems/p-vs-np","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-005","domain":"数学与计算","subdomain":"计算理论","title":"计算复杂性层级","description":"P、NP、PSPACE、EXPTIME等复杂性类之间的精确包含关系，特别是P vs PSPACE和NP vs coNP。","current_state":"时间层级定理确认P≠EXPTIME；但P vs NP、NP vs coNP、P vs PSPACE仍开放；量子复杂性类BQP的位置(是否在NP之外)也未知。","key_directions":["电路下界证明(ACC0等弱电路类)","代数复杂性(VP vs VNP)","量子复杂性与经典复杂性的分离","平均情况复杂性vs最坏情况"],"impact":4,"difficulty":5,"timeline":"未知","related":["MAT-001"],"sources":[{"text":"CCC Conference 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"MAT-006","domain":"数学与计算","subdomain":"AI 理论","title":"通用人工智能(AGI)","description":"构建在所有认知任务上达到或超越人类水平的AI系统。这是AI领域的终极目标。","current_state":"GPT-4/Claude/Gemini等大语言模型在许多任务上接近或超越人类但仍有系统性缺陷(推理/规划/长程一致性)；o1/o3类推理模型在数学/编程上表现突出；Scaling Laws仍在持续但边际效益递减引发争议。","key_directions":["推理与规划能力(系统2思维)","世界模型与因果理解","具身智能与多模态融合","持续学习与记忆","AI能力评估基准(超越静态benchmark)"],"impact":5,"difficulty":5,"timeline":"5-20年","related":["INF-001","MAT-007"],"sources":[{"text":"OpenAI o3 2024","url":"https://openai.com/index/introducing-o3-and-o4-mini/","type":"official"},{"text":"Anthropic Claude 2024","url":"https://www.anthropic.com/news/claude-3-5-sonnet","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-007","domain":"数学与计算","subdomain":"AI 理论","title":"AI可解释性与学习理论","description":"深度学习为什么有效?泛化的理论基础是什么?模型内部表示如何可解释?","current_state":"双下降现象被确认但理论不完整；机械可解释性(mechanistic interpretability)进展显著(2024年发现大模型中的特定特征/电路)；PAC-Bayes界在深度学习中有新应用；但统一理论仍不存在。","key_directions":["深度学习泛化的统一理论","机械可解释性：逆向工程神经网络","Scaling Laws的理论基础","in-context学习机制","表示学习的信息几何"],"impact":5,"difficulty":5,"timeline":"5-20年","related":["MAT-006","INF-001"],"sources":[{"text":"Anthropic Interpretability 2024","url":"https://www.anthropic.com/news/mapping-mind-language-model","type":"official"},{"text":"NeurIPS 2024","url":"https://neurips.cc/","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-008","domain":"数学与计算","subdomain":"量子计算","title":"量子计算优越性","description":"量子计算机在特定问题上实现经典计算机无法匹敌的计算速度。","current_state":"Google Sycamore(2019)和 中国九章(2020)分别实现了随机线路采样和高斯玻色采样的量子优越性；但有用问题的量子优越性尚未实现；2024年Google Willow芯片实现纠错下的计算增益。","key_directions":["容错量子计算(表面码纠错)","量子算法在实用问题上的优势(化学/优化/机器学习)","NISQ时代的量子应用","量子纠错码的阈值改进"],"impact":5,"difficulty":5,"timeline":"10-20年","related":["MAT-009","INF-003"],"sources":[{"text":"Google Willow 2024","url":"https://blog.google/technology/research/google-willow-quantum-chip/","type":"official"},{"text":"Nature 2024 Quantum","url":"https://www.nature.com/articles/s41586-024-08449-y","type":"paper"}],"last_updated":"2026-07"},{"id":"MAT-009","domain":"数学与计算","subdomain":"量子计算","title":"量子纠错与容错计算","description":"量子比特极易受噪声干扰，实现可靠的量子计算需要量子纠错码和容错协议。","current_state":"Google Willow(2024)首次在实验中展示表面码增大(3→5→7)时错误率降低，实现'below threshold'；但逻辑量子比特数还远不够做有用计算(需~1000+逻辑比特)。","key_directions":["表面码与色码的优化","LDPC量子码(更高编码率)","容错量子逻辑门(魔幻态蒸馏优化)","纠错开销的降低"],"impact":5,"difficulty":5,"timeline":"10-20年","related":["MAT-008"],"sources":[{"text":"Google Willow 2024","url":"https://blog.google/technology/research/google-willow-quantum-chip/","type":"official"}],"last_updated":"2026-07"},{"id":"MAT-010","domain":"数学与计算","subdomain":"量子计算","title":"后量子密码学","description":"量子计算机可破解RSA/ECC等当前加密标准，需开发抗量子攻击的密码体系。","current_state":"NIST已标准化第一批后量子密码算法(ML-KEM/ML-DSA/SLH-DSA)；全球互联网正逐步迁移到后量子密码；但迁移过程漫长且存在混合方案的兼容性问题。","key_directions":["后量子密码的全球迁移路径","全同态加密的效率优化","量子密钥分发(QKD)与PQC的互补","基于格的密码安全性分析"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["INF-003","INF-005"],"sources":[{"text":"NIST PQC 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"MAT-011","domain":"数学与计算","subdomain":"数学机械化","title":"自动定理证明与形式化验证","description":"AI辅助的自动定理证明和计算机形式化数学，目标是自动化数学发现。","current_state":"Lean 4/Mathlib 形式化数学库快速增长；AlphaProof(DeepMind)在IMO级别数学题上取得银牌水平；AI辅助证明在组合学/数论中有实际贡献。Tao等数学家开始日常使用Lean。","key_directions":["AI驱动的定理发现(不只是证明)","Lean/Mathlib的形式化覆盖率","大语言模型+形式化验证的组合系统","自动发现新的数学结构和关系"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["MAT-001","MAT-006"],"sources":[{"text":"DeepMind AlphaProof 2024","url":"","type":"paper"},{"text":"Lean Mathlib 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"MAT-012","domain":"数学与计算","subdomain":"计算理论","title":"可计算性与算法信息论","description":"什么是可计算的?随机性的本质是什么?Kolmogorov复杂性的深刻问题。","current_state":"Chatin不完全性定理与算法信息论持续深化；2024年在随机性检验和伪随机性生成方面有进展；计算与物理的关系(Lloyd计算宇宙观)成为热点。","key_directions":["算法随机性与可计算性","量子算法信息论","物理过程的计算复杂性(物理=计算?)","信息与热力学深层联系(Landauer原理)"],"impact":3,"difficulty":5,"timeline":"未知","related":["PHY-011"],"sources":[{"text":"Algorithmic Information Theory 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-001","domain":"宇宙学","subdomain":"宇宙起源","title":"暴胀理论验证","description":"宇宙在极早期是否经历过指数膨胀?暴胀的原初引力波信号(B模偏振)是关键证据。","current_state":"BICEP/Keck持续降低张量-标量比r的上限(r<0.036 at 95% CL)；CMB-S4计划将灵敏度提升一个数量级；若r<10^-3，许多暴胀模型将被排除。","key_directions":["CMB-S4对原初引力波(B模)的搜索","LiteBIRD空间CMB偏振探测","暴胀模型的可检验预测","非高斯性作为暴胀探针"],"impact":5,"difficulty":4,"timeline":"10-20年","related":["PHY-010","COS-002"],"sources":[{"text":"BICEP/Keck 2024","url":"https://arxiv.org/abs/2405.19469","type":"paper"},{"text":"CMB-S4 Design Report","url":"https://cmb-s4.org/","type":"official"}],"last_updated":"2026-07"},{"id":"COS-002","domain":"宇宙学","subdomain":"黑洞物理","title":"黑洞信息悖论","description":"信息落入黑洞后是否在霍金辐射中逃逸?这关乎量子力学的么正性。","current_state":"Page曲线的理论计算(利用全息熵公式)显示信息可以被恢复；'量子极值面'的发现解决了信息悖论的数学表述；但物理机制(纠缠如何逃逸)仍不清楚。","key_directions":["Page曲线的物理机制解释","黑洞内部结构(火墙/ER桥/模糊球)","AdS/CFT中的信息恢复过程","引力波观测对黑洞无毛定理的检验"],"impact":5,"difficulty":5,"timeline":"20-50年","related":["PHY-009","PHY-010"],"sources":[{"text":"Penington 2024","url":"https://arxiv.org/abs/2404.16098","type":"paper"},{"text":"Nature Physics 2024 BH Info","url":"https://arxiv.org/abs/2406.13949","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-003","domain":"宇宙学","subdomain":"宇宙结构","title":"暗能量与宇宙命运","description":"宇宙加速膨胀将持续多久?宇宙的终极命运是大撕裂、热寂还是大坍缩?","current_state":"DESI 2024数据暗示暗能量可能演化(phantom crossing?)，若确认将改变宇宙命运预测；当前数据仍与ΛCDM一致但张力增大。","key_directions":["暗能量状态方程w(z)的精确测量","宇宙学常数vs动力学暗能量的判别","宇宙命运的理论预测(大撕裂/热寂/反弹)","Hubble张力对暗能量模型的约束"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["PHY-002","COS-001"],"sources":[{"text":"DESI 2024 DR1","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-004","domain":"宇宙学","subdomain":"地外生命","title":"系外生命探测","description":"在太阳系外行星上发现生命信号(生物标记气体)，回答'我们是孤独的吗?'","current_state":"JWST探测到K2-18b大气中可能的二甲基硫(DMS)信号(争议中)；TRAPPIST-1系统的行星大气特征化进行中；下一代望远镜(HabEx/LUVOIR概念)仍在规划。","key_directions":["JWST对类地系外行星大气的精细光谱","生物标记气体(O2/CH4/DMS)的探测与排除假阳性","直接成像技术(日冕仪/星影)","ELT极大望远镜的系外行星观测"],"impact":5,"difficulty":4,"timeline":"10-30年","related":["LIF-004","COS-005"],"sources":[{"text":"JWST K2-18b 2024","url":"https://arxiv.org/abs/2406.08436","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-005","domain":"宇宙学","subdomain":"地外生命","title":"费米悖论与宇宙大沉默","description":"如果宇宙中有大量宜居行星，为什么我们没看到任何外星文明的迹象?","current_state":"Breakthrough Listen等SETI项目未检测到确凿技术信号；2023年有疑似信号(BLC1)后被排除；系外行星统计确认宜居行星普遍存在，加剧了悖论。","key_directions":["技术签名(戴森球/异常光谱/窄带射电)","大过滤器假说的检验","黑暗森林假说与社会学模型","系外行星技术签名的大规模巡天"],"impact":5,"difficulty":4,"timeline":"未知","related":["COS-004","SOC-008"],"sources":[{"text":"Breakthrough Listen 2024","url":"https://iopscience.iop.org/article/10.3847/1538-3881/ad7e18","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-006","domain":"宇宙学","subdomain":"黑洞物理","title":"黑洞内部结构与奇点","description":"黑洞内部是什么?奇点是否真实存在还是广义相对论的失效信号?","current_state":"2019年EHT首张黑洞照片(M87)；2024年EHT持续改进分辨率；黑洞内部无法直接观测，但引力波可以提供约束；圈量子引力预测奇点被量子反弹取代。","key_directions":["黑洞阴影的精确测量(EHT/ngEHT)","引力波对黑洞无毛定理的检验","量子引力对奇点的替代(反弹/模糊球)","黑洞热力学与面积定理的验证"],"impact":4,"difficulty":5,"timeline":"20-50年","related":["COS-002","PHY-009"],"sources":[{"text":"EHT 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-007","domain":"宇宙学","subdomain":"宇宙起源","title":"前大爆炸物理","description":"大爆炸之前是什么?宇宙是否从量子涨落中诞生?循环宇宙还是一次性事件?","current_state":"暴胀理论暗示宇宙可能从量子涨落产生；循环宇宙模型(彭罗斯CCC)有观测声称但争议极大；弦论宇宙学提供前大碰撞场景但不可检验。","key_directions":["暴胀预言的可检验性(原初引力波)","循环宇宙模型的天文检验","量子宇宙学(波函数隧穿)","多重宇宙的可观测性边界"],"impact":5,"difficulty":5,"timeline":"30-100年","related":["COS-001","PHY-009"],"sources":[{"text":"Penrose CCC 2024","url":"https://arxiv.org/abs/2208.06021","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-008","domain":"宇宙学","subdomain":"多元宇宙","title":"多元宇宙可检验性","description":"弦论景观和暴胀多重宇宙预测存在不可观测的其他宇宙，这对科学可检验性提出根本挑战。","current_state":"暴胀永恒性预测存在不可观测的区域；弦景观~10^500个真空；人择原理被用来解释精细调节问题；但可检验性争议巨大。","key_directions":["多重宇宙的可检验预测(碰撞痕迹?)","暴胀非高斯性作为多重宇宙信号","弦论Swampland约束的可检验性","科学与不可检验性的哲学边界"],"impact":4,"difficulty":5,"timeline":"未知","related":["COS-007","PHY-012"],"sources":[{"text":"Universe 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-009","domain":"宇宙学","subdomain":"宇宙结构","title":"大尺度结构与Hubble张力","description":"宇宙学距离阶梯测量的Hubble常数与CMB推导的值不一致(Hubble张力)，可能暗示新物理。","current_state":"SH0ES测量H0=73.04±1.04；Planck CMB推导H0=67.4±0.5；5sigma张力持续；JWST确认SH0ES测量未被系统误差污染；早期暗能量模型是最热门解释但未确认。","key_directions":["JWST对造父变星/RG星距离阶梯的验证","早期暗能量模型","新物理vs系统误差的最终判别","引力波标准警笛对H0的独立测量"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["PHY-002","COS-003"],"sources":[{"text":"SH0ES/JWST 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"COS-010","domain":"宇宙学","subdomain":"宇宙结构","title":"暗物质晕子结构缺失问题","description":"矮星系中暗物质晕的子结构数量远低于冷暗物质预测，可能暗示暗物质性质(温暗物质/自相互作用)或重子反馈。","current_state":"重子反馈可以部分解释；但最暗矮星系仍存在张力；自相互作用暗物质(ISDM)约束日益严格；未来LSST将发现更多超暗矮星系。","key_directions":["LSST发现超暗矮星系","暗物质自相互作用约束","温暗物质/模糊暗物质模型","暗物质晕密度剖面的精确测量"],"impact":3,"difficulty":3,"timeline":"5-10年","related":["PHY-001"],"sources":[{"text":"DES 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-001","domain":"材料与能源","subdomain":"储能与电池","title":"固态电池","description":"用固体电解质替代液态电解液，实现更高能量密度和更安全的锂电池。","current_state":"丰田/QuantumScape/Solid Power等推进硫化物/氧化物固态电解质；2024年半固态电池已量产装车；全固态电池预计2027-2030年量产；锂金属负极界面稳定性仍是核心挑战。","key_directions":["硫化物电解质的化学稳定性","锂金属负极界面工程","固态电池的规模化制造工艺","钠基固态电池(降低锂依赖)"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["ENG-002"],"sources":[{"text":"Toyota Solid State 2024","url":"","type":"paper"},{"text":"Nature Energy 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-002","domain":"材料与能源","subdomain":"储能与电池","title":"新型储能机制","description":"超越锂离子电池的新型储能：锂硫、锂空气、钠离子、多价离子(Mg/Ca)电池。","current_state":"钠离子电池已量产(CATL)；锂硫电池循环寿命持续改善(>1000次)但仍未规模化；锂空气电池效率仍低；多价离子电池基础研究阶段。","key_directions":["锂硫电池的多硫化物穿梭抑制","锂空气电池的催化剂设计","钠离子电池能量密度提升","水系电池(安全性/大规模储能)"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["ENG-001"],"sources":[{"text":"CATL Sodium 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-003","domain":"材料与能源","subdomain":"碳中和技术","title":"直接空气碳捕集(DAC)","description":"从大气中直接捕集CO2，是实现负排放和碳中和的关键技术。","current_state":"Climeworks/Carbon Engineering等推进DAC商业化；2024年大型DAC工厂在冰岛/美国投入运营；但能耗和成本仍高($200-600/吨CO2)，需降至$100/吨以下才具规模意义。","key_directions":["高效CO2吸附材料(金属有机框架MOF)","低温再生工艺降能耗","DAC+地质封存的规模化","DAC+利用(合成燃料/碳酸盐)的经济性"],"impact":5,"difficulty":4,"timeline":"10-20年","related":["EAR-001"],"sources":[{"text":"Climeworks 2024","url":"https://climeworks.com/press-release/climeworks-switches-on-worlds-largest-direct-air-capture-plant-mammoth","type":"official"},{"text":"IEA DAC Report 2024","url":"https://www.iea.org/energy-system/carbon-capture-utilisation-and-storage/direct-air-capture","type":"official"}],"last_updated":"2026-07"},{"id":"ENG-004","domain":"材料与能源","subdomain":"碳中和技术","title":"人工光合作用","description":"模仿自然光合作用，用太阳能将CO2和水转化为燃料或化学品。","current_state":"光催化分解水的太阳能-氢能转化效率(STH)突破1%但仍远低于10%商业化阈值；光电催化CO2还原效率提升；单原子催化剂是热点。","key_directions":["光催化全分解水效率突破","光电催化CO2还原选择性","生物-无机杂化系统(半导体+细菌)","串联/叠层器件设计"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["ENG-003","CHE-001"],"sources":[{"text":"Nature Catalysis 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-005","domain":"材料与能源","subdomain":"前沿材料","title":"二维材料与范德华异质结","description":"将不同二维材料(石墨烯/BN/MoS2等)堆叠成异质结，创造全新物性和器件。","current_state":"魔角石墨烯超导持续深入研究；二维半导体验证性器件性能提升；2024年有研究实现大面积单晶二维材料的可控生长；但规模化转移和异质结制备仍是挑战。","key_directions":["魔角石墨烯的非常规超导机制","二维半导体晶体管超越硅","大规模可控生长与转移","二维磁体与自旋电子学"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["PHY-006","PHY-014"],"sources":[{"text":"Nature 2024 2D Materials","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-006","domain":"材料与能源","subdomain":"核能","title":"第四代核反应堆","description":"下一代核反应堆(熔盐堆/高温气冷堆/快堆)提高安全性、效率和核燃料利用率。","current_state":"中国石岛湾高温气冷堆(HTR-PM)2023年商业运行；中国钍基液态燃料实验堆(TMSR)建设中；美国NuScale小型模块化反应堆(SMR)设计认证但项目取消；TerraPower Natrium示范堆在建。","key_directions":["钍基熔盐堆的工程化验证","小型模块化反应堆(SMR)经济性","快中子堆的核燃料闭式循环","核反应堆的固有安全性设计"],"impact":5,"difficulty":4,"timeline":"5-15年","related":["PHY-007"],"sources":[{"text":"CNNC HTR-PM 2024","url":"https://www.neimagazine.com/news/chinas-htr-pm-heating-project-begins-operation-11658937","type":"official"},{"text":"TerraPower 2024","url":"https://www.terrapower.com/","type":"official"}],"last_updated":"2026-07"},{"id":"ENG-007","domain":"材料与能源","subdomain":"氢能","title":"高效电解水制氢","description":"用可再生能源驱动电解水产生绿氢，是氢能经济的关键环节。","current_state":"碱性电解槽(AWE)成本最低但效率有限；PEM电解槽效率高但依赖贵金属铱；2024年AEM电解槽成为新热点(结合低成本和高效率)；绿氢成本约$4-6/kg，需降至$2/kg。","key_directions":["AEM电解槽的非贵金属催化剂","高温固体氧化物电解(SOEC)","海水电解的直接耦合","光伏-电解一体化设计"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["ENG-004"],"sources":[{"text":"Nature Energy 2024 Hydrogen","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-008","domain":"材料与能源","subdomain":"前沿材料","title":"超材料与变换光学","description":"人工设计的微结构材料，实现自然界不存在的电磁/声学/力学性质(负折射/隐身/超透镜)。","current_state":"超透镜(metalens)开始商业化(消费电子/AR/VR)；声学超材料用于噪声控制；力学超材料(负泊松比/拉胀)在生物医学中应用；可编程超材料是前沿。","key_directions":["可编程/可重构超材料","宽带超透镜(可见光全波段)","超材料隐身的实用化","拓扑超材料与单向传播"],"impact":3,"difficulty":3,"timeline":"5-15年","related":["ENG-005"],"sources":[{"text":"Nature Materials 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-009","domain":"材料与能源","subdomain":"前沿材料","title":"仿生材料与自修复材料","description":"模仿生物体的自修复、自适应、传感功能的智能材料。","current_state":"自修复聚合物在涂层/电子皮肤中应用；4D打印(形状记忆)材料发展；人工肌肉材料(介电弹性体/碳纳米管纱线)性能提升；但自修复效率与机械性能的权衡仍是挑战。","key_directions":["高效自修复聚合物(室温/快速)","自修复电子器件与电路","生物-材料界面(植入物)","自适应变形结构(航空航天)"],"impact":3,"difficulty":3,"timeline":"5-15年","related":[],"sources":[{"text":"Advanced Materials 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"ENG-010","domain":"材料与能源","subdomain":"碳中和技术","title":"聚变-裂变混合堆","description":"利用聚变中子驱动裂变燃料增殖或嬗变，降低纯聚变的工程门槛。","current_state":"概念设计和部分实验验证阶段；中国ZN混合堆概念研究推进；可能作为纯聚变堆的过渡方案；但政治和核扩散考量是障碍。","key_directions":["聚变中子源驱动的次临界裂变堆","核废料嬗变的工程化","钍增殖的聚变-裂变方案","安全性与核不扩散设计"],"impact":3,"difficulty":4,"timeline":"20-30年","related":["PHY-007","ENG-006"],"sources":[{"text":"Nuclear Fusion 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-001","domain":"信息与智能","subdomain":"AI 安全","title":"AGI 对齐与价值观学习","description":"如何确保超级AI系统的目标与人类价值观一致?这是AI安全的核心问题。","current_state":"Constitutional AI(RLHF/RLAIF)成为主流对齐方法；2024年研究聚焦于 scalable oversight(人类监督AI时的能力瓶颈)和 deceptive alignment(模型假装对齐)；但理论框架远未成熟。","key_directions":["Scalable oversight(可扩展监督)","Mechanistic interpretability for alignment","Constitutional AI与价值观的规范表述","欺骗性对齐的检测与预防","多AI博弈中的对齐(Consensus/Debate)"],"impact":5,"difficulty":5,"timeline":"5-15年","related":["MAT-006","MAT-007"],"sources":[{"text":"Anthropic Alignment 2024","url":"https://www.anthropic.com/research/alignment-faking","type":"official"},{"text":"OpenAI Superalignment 2024","url":"https://openai.com/index/introducing-superalignment/","type":"official"}],"last_updated":"2026-07"},{"id":"INF-002","domain":"信息与智能","subdomain":"脑机接口","title":"高带宽脑机接口","description":"实现大脑与计算机之间高带宽、双向信息传输，从恢复残障功能到增强认知。","current_state":"Neuralink 2024年实现首例人体植入(BMI光标控制)；Pennsylvania大学无创超声脑机接口进展；但带宽(目前<100bps)远低于实用需求(>1Mbps)；双向写入仍是挑战。","key_directions":["柔性高密度电极阵列(>10000通道)","无创/微创脑机接口(超声/fMRI)","双向闭环脑机接口(读取+写入)","神经解码算法(deep learning)","长期植入的生物相容性"],"impact":5,"difficulty":5,"timeline":"10-20年","related":["LIF-001","LIF-002"],"sources":[{"text":"Neuralink 2024","url":"https://neuralink.com/updates/a-year-of-telepathy/","type":"official"},{"text":"Nature Medicine 2024 BCI","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-003","domain":"信息与智能","subdomain":"量子信息","title":"量子通信网络与量子互联网","description":"构建基于量子纠缠的全球通信网络，实现无条件安全的通信和分布式量子计算。","current_state":"中国墨子号卫星实现千公里级量子密钥分发；城域量子网络(北京/合肥/上海)运行；但量子中继器(长程纠缠分发)效率仍低；量子互联网原型距离实用化尚远。","key_directions":["高效量子中继器(存储器+纠缠交换)","星地一体化量子网络","量子互联网协议栈","设备无关量子密钥分发"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["MAT-008","MAT-010"],"sources":[{"text":"Nature 2024 Quantum Internet","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-004","domain":"信息与智能","subdomain":"计算架构","title":"后摩尔时代计算架构","description":"摩尔定律放缓后，通过新架构(类脑/光子/存算一体/3D堆叠)延续算力增长。","current_state":"存算一体(CIM)芯片在AI推理中展示能效优势；光子芯片(Lightmatter)进入商用；Intel TSMC推进3D堆叠(Foveros/CoWoS)；神经形态芯片(Intel Loihi2/IBM NorthPole)在低功耗AI中验证。","key_directions":["光子计算(矩阵乘法加速)","存算一体(模拟CIM/数字CIM)","神经形态计算(脉冲神经网络)","3D异构集成与芯粒(chiplet)","碳纳米管/二维材料晶体管"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["ENG-005","INF-005"],"sources":[{"text":"Nature Electronics 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-005","domain":"信息与智能","subdomain":"计算架构","title":"DNA 信息存储","description":"用DNA分子作为超高密度(10^18 bytes/mm^3)、超长寿命(千年)的信息存储介质。","current_state":"已实现MB级数据的DNA存储读写；2024年有研究实现自动化的DNA数据存储系统；但写入(合成)成本仍极高($800M/GB)且速度慢；随机读取(索引)效率待提升。","key_directions":["DNA合成的低成本化(酶法vs化学法)","随机读取的索引与检索机制","DNA数据存储的编码理论","超大量级(PB+)DNA存储的工程化"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["INF-004"],"sources":[{"text":"Nature 2024 DNA Storage","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-006","domain":"信息与智能","subdomain":"AI 安全","title":"AI 安全保障与红队","description":"系统性发现和缓解AI系统中的安全漏洞(越狱/数据投毒/后门/对抗样本)。","current_state":"大模型越狱(jailbreak)攻防持续升级；AI红队工具自动化程度提高；2024年多起AI深度伪造(deepfake)引发安全事件；AI安全标准(ISO/IEC 42001)开始制定。","key_directions":["自动化AI红队测试","深度伪造检测与溯源","对抗鲁棒性训练","AI系统安全监控与审计","AI生成内容的水印与来源追踪"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["INF-001"],"sources":[{"text":"NIST AI RMF 2024","url":"","type":"paper"},{"text":"OpenAI Red Teaming 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-007","domain":"信息与智能","subdomain":"AI 安全","title":"AI 治理与全球监管框架","description":"建立全球协调的AI治理框架，在促进创新和管控风险之间取得平衡。","current_state":"EU AI Act 2024年生效(全球首部AI综合法律)；中国AI法规(深度合成/生成式AI管理办法)已实施；美国行政令+自愿承诺；但全球协调机制远未形成。","key_directions":["AI风险评估框架(系统性/灾难性风险)","前沿AI模型的国际监管协调","算力治理作为监管杠杆","开源AI模型的治理路径","AI军事应用的规范"],"impact":4,"difficulty":4,"timeline":"5-10年","related":["INF-001","INF-006"],"sources":[{"text":"EU AI Act 2024","url":"","type":"paper"},{"text":"Bletchley Declaration 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-008","domain":"信息与智能","subdomain":"计算架构","title":"神经形态计算","description":"模仿大脑结构和计算原理的芯片架构，实现超低功耗的实时智能计算。","current_state":"Intel Loihi 2和IBM NorthPole展示在边缘AI中的能效优势；脉冲神经网络(SNN)训练算法进展；但与深度学习的性能差距仍大；标准化的SNN开发工具尚不成熟。","key_directions":["脉冲神经网络训练算法","在线学习与持续适应","神经形态芯片的生态系统(SNN框架)","感存算一体化传感器"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["INF-004","INF-002"],"sources":[{"text":"Intel Loihi 2 2024","url":"","type":"paper"},{"text":"IBM NorthPole 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-009","domain":"信息与智能","subdomain":"量子信息","title":"分布式量子计算与量子网络","description":"通过量子网络连接多个量子处理器，实现可扩展的分布式量子计算。","current_state":"两个量子处理器间的量子隐形传态已实验验证；但远程纠缠保真度和速率不足以支撑计算；光子互连的量子处理器是主流路线。","key_directions":["量子处理器互连(光子/微波)","分布式量子算法与量子网络协议","远程纠缠分发的高保真度","模块化量子计算机架构"],"impact":4,"difficulty":5,"timeline":"15-30年","related":["MAT-008","INF-003"],"sources":[{"text":"Nature 2024 Distributed QC","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"INF-010","domain":"信息与智能","subdomain":"AI 安全","title":"AI 驱动的科学发现","description":"用AI加速科学发现：从材料到药物到数学证明，AI正成为科学研究的核心工具。","current_state":"AlphaFold(蛋白质结构)、GNoME(新材料发现)、AlphaProof(数学证明)等突破；AI辅助的药物设计加速；但AI发现的科学可解释性和可验证性仍是挑战。2024年AI4Science成为学术界热点。","key_directions":["AI驱动的材料发现(高通量+实验闭环)","AI辅助的数学发现与证明","AI加速的药物设计(从靶点到分子)","AI科学发现的可靠性验证","自动化实验室(AI+机器人)"],"impact":5,"difficulty":3,"timeline":"5-10年","related":["LIF-008","MAT-011","ENG-005"],"sources":[{"text":"DeepMind GNoME 2023","url":"https://www.nature.com/articles/s41586-023-06735-9","type":"paper"},{"text":"Nature AI4Science 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-001","domain":"地球科学与气候","subdomain":"气候科学","title":"气候敏感度精确确定","description":"CO2浓度翻倍导致的全球平均温度升高(平衡气候敏感度ECS)的确切值，是气候预测的核心参数。","current_state":"IPCC AR6评估ECS范围2.5-4.0°C(很可能3.0°C)；古气候和能量收支约束收窄了范围但不确定性仍大；云反馈是最大不确定来源。","key_directions":["云反馈机制的观测约束","高分辨率气候模型(storm-resolving)","古气候代用指标对ECS的约束","AI辅助的气候模型参数优化"],"impact":5,"difficulty":4,"timeline":"5-10年","related":["EAR-002"],"sources":[{"text":"IPCC AR6 2023","url":"https://www.ipcc.ch/report/ar6/syr/","type":"official"},{"text":"Nature Climate 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-002","domain":"地球科学与气候","subdomain":"气候科学","title":"气候临界点与级联效应","description":"地球系统中存在多个临界点(格陵兰冰盖/AMOC/亚马逊雨林/永久冻土)，一个临界点可能触发级联效应。","current_state":"2024年研究表明多个临界点可能已在触发中(格陵兰冰盖/珊瑚礁)；AMOC减弱的信号增强但是否越过临界点尚不确定；临界点间的级联机制研究刚起步。","key_directions":["AMOC稳定性的早期预警信号","格陵兰/南极冰盖的不稳定性监测","临界点级联效应的模型研究","亚马逊雨林向碳源转变的阈值"],"impact":5,"difficulty":4,"timeline":"5-20年","related":["EAR-001"],"sources":[{"text":"Science 2024 Tipping Points","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-003","domain":"地球科学与气候","subdomain":"固体地球","title":"地震预测与预警","description":"能否实现可靠的地震预测(时间/地点/震级)?当前只能做到秒级预警和长期概率评估。","current_state":"地震预警系统(EEW)在多国运行(日本/墨西哥/中国/美国西海岸)；但可靠的短期预测仍未实现；AI辅助的地震信号识别提高预警速度；慢滑移与地震触发关系研究深入。","key_directions":["AI驱动的地震信号识别与预警","慢滑移与地震触发的物理模型","GPS/InSAR对地壳形变的连续监测","统计地震学的预测模型改进"],"impact":5,"difficulty":5,"timeline":"未知(可能不可预测)","related":["EAR-004"],"sources":[{"text":"Nature 2024 Earthquake Prediction","url":"https://www.nature.com/articles/s41467-024-51596-z","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-004","domain":"地球科学与气候","subdomain":"固体地球","title":"地球深内部结构与动力学","description":"地幔和地核的结构、成分和动力学过程，包括大型低剪切速度省(LLSVPs)的本质。","current_state":"地震层析成像揭示地幔柱和俯冲板片的形态；LLSVPs(非洲/太平洋)的本质(化学vs热异常)仍有争议；内核超速旋转和各向异性有新约束。","key_directions":["高分辨率全地幔层析成像","LLSVPs的化学vs热本质判别","地核-地幔边界(CMB)过程","地磁场起源与地核动力学"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["EAR-003"],"sources":[{"text":"Nature Geoscience 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-005","domain":"地球科学与气候","subdomain":"生态与环境","title":"生物多样性丧失与生态系统功能","description":"量化生物多样性丧失对生态系统功能(碳汇/水循环/食物网)的影响，预测生态系统崩溃临界点。","current_state":"IPBES报告确认全球生物多样性持续下降；功能多样性与生态系统功能的关系深入研究；但多营养级、多生态系统的综合预测模型仍不成熟。","key_directions":["功能多样性vs分类多样性的预测价值","生态系统多功能性的量化","生态网络鲁棒性与临界点","遥感+AI的大规模生物多样性监测"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["LIF-007","EAR-002"],"sources":[{"text":"IPBES 2024","url":"","type":"paper"},{"text":"Nature Ecology 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-006","domain":"地球科学与气候","subdomain":"气候科学","title":"气候工程(Geoengineering)可行性与风险","description":"通过人为干预地球系统(平流层气溶胶/海洋云增白/碳捕集)缓解气候变化，但风险巨大。","current_state":"SCoPEx(平流层气溶胶实验)多次推迟，2024年仍处于治理讨论阶段；海洋云增白有小型野外试验；全球治理框架(UNEP评估)推进缓慢。","key_directions":["平流层气溶胶注入的气候效应模拟","终止冲击(termination shock)的风险","海洋云增白的区域试验","国际治理框架与伦理"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["EAR-001","EAR-002"],"sources":[{"text":"UNEP Geoengineering 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-007","domain":"地球科学与气候","subdomain":"固体地球","title":"板块构造起源","description":"地球板块构造何时开始?驱动力是什么?为什么地球是太阳系中唯一有活跃板块构造的行星?","current_state":"板块起源时间争议从4.4Ga到2.8Ga；锆石氧同位素和变质岩记录提供线索；2024年新研究支持早期俯冲证据。地幔粘度和水的角色是核心争议。","key_directions":["早期地球热演化的数值模拟","古地磁与超大陆重建","金星/火星比较行星学","板块构造启动的临界条件(水/温度/成分)"],"impact":3,"difficulty":4,"timeline":"10-30年","related":["EAR-004","SPA-004"],"sources":[{"text":"Nature Geoscience 2024 Plate Tectonics","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"EAR-008","domain":"地球科学与气候","subdomain":"气候科学","title":"极端天气归因与预测","description":"将极端天气事件(热浪/洪涝/台风)归因于气候变化，并提高次季节到季节的极端天气预测。","current_state":"归因科学成熟度提高，热浪归因置信度最高；AI/ML在次季节预测中展示潜力；但极端降水的归因和预测仍具挑战。","key_directions":["AI驱动的次季节极端预测","极端事件归因的快速响应系统","复合极端事件(热浪+干旱+火灾)","城市微气候与极端天气"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["EAR-001"],"sources":[{"text":"World Weather Attribution 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-001","domain":"化学","subdomain":"催化","title":"非贵金属催化体系","description":"用廉价丰产元素替代Pt/Pd/Ru等贵金属催化剂，降低化工和能源成本。","current_state":"单原子催化剂(SAC)在多种反应中展示接近贵金属的活性；2024年有多个非贵金属电催化(HER/OER/ORR)研究突破；但工业化的长期稳定性验证仍不足。","key_directions":["单原子催化剂的精确设计与规模化","非贵金属电催化(水电解/燃料电池)","酶催化的机理启发设计","光催化/电催化CO2还原的非贵金属体系"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["ENG-007","LIF-008"],"sources":[{"text":"Nature Catalysis 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-002","domain":"化学","subdomain":"分子机器","title":"分子机器与分子马达","description":"设计和合成在纳米尺度自主运动的分子机器，实现分子级加工/运输/信息处理。","current_state":"2016年诺贝尔化学奖授予分子机器；2024年分子马达的能量效率和控制精度提升；但分子机器的集体协同行为和宏观功能输出仍是挑战。","key_directions":["分子马达的自主性和方向性控制","分子机器的集体行为","分子级信息处理与计算","分子机器驱动的纳米加工"],"impact":3,"difficulty":4,"timeline":"15-30年","related":["LIF-008"],"sources":[{"text":"Chemical Society Reviews 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-003","domain":"化学","subdomain":"绿色化学","title":"塑料的化学回收与升级","description":"将废弃塑料化学分解为单体或转化为更高价值化学品，解决塑料污染问题。","current_state":"化学解聚(PET→BHET)技术成熟并商业化；聚烯烃(PE/PP)的化学回收更难但2024年有新催化突破；酶法降解PET的效率持续提升。","key_directions":["聚烯烃(PE/PP/PS)的选择性化学解聚","工程化酶降解混合塑料","塑料到高价值化学品的升级回收","可化学回收的新型聚合物设计"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["ENG-003"],"sources":[{"text":"Nature 2024 Plastic Recycling","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-004","domain":"化学","subdomain":"理论化学","title":"精确电子结构计算","description":"多电子体系的精确量子化学计算——从计算角度解决薛定谔方程，对化学/材料/药物至关重要。","current_state":"CCSD(T)作为'黄金标准'但限于中小分子；DMRG/FCIQMC处理强关联体系；2024年AI辅助的波函数方法(如FermiNet/PauliNet)在精确性上取得突破但计算量大。","key_directions":["AI驱动的波函数 Ansatz(FermiNet等)","量子计算辅助的电子结构(QPE/VQE)","强关联体系的精确方法","大分子体系的线性标度方法"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["MAT-008","LIF-008"],"sources":[{"text":"Science 2024 Quantum Chemistry AI","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-005","domain":"化学","subdomain":"合成化学","title":"惰性键的选择性活化","description":"选择性断裂C-H/C-C/N2等惰性化学键，实现从简单原料高效合成复杂分子。","current_state":"C-H键活化在药物合成中广泛应用；但通用性和选择性仍有挑战；2024年有光电协同催化活化惰性键的新策略。","key_directions":["C-H键活化的区域/立体选择性控制","C-C键选择性断裂与重组","N2活化与常温合成氨","电/光/酶协同催化"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["CHE-001","CHE-006"],"sources":[{"text":"JACS 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-006","domain":"化学","subdomain":"超重元素化学","title":"超重元素化学性质","description":"研究超重元素(Z>103)的化学性质，检验相对论效应如何改变元素行为。","current_state":"气相色谱实验研究了Rf/Db/Sg/Bh/Hs/Mt/Cn等超重元素的挥发性;2024年对Fl(114)的化学性质有初步结果;但单原子化学实验极具挑战。","key_directions":["超重元素(119/120)的化学性质预测","相对论效应的量化验证","超重元素在水溶液中的化学","自动化的单原子化学实验平台"],"impact":3,"difficulty":5,"timeline":"10-20年","related":["PHY-015"],"sources":[{"text":"GSI/RIKEN 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-007","domain":"化学","subdomain":"合成化学","title":"AI驱动的逆合成分析与路线设计","description":"用AI自动化设计从简单原料到目标分子的最优合成路线。","current_state":"Chematica/Synthia等逆合成软件广泛使用；2024年LLM辅助的合成路线设计出现；自动化合成机器人(机器人化学家)与AI路线规划结合；但在复杂天然产物合成上仍逊于人类专家。","key_directions":["AI合成路线设计的准确性与多样性","机器人化学家的自动化实验闭环","反应预测(产率/选择性)的ML模型","AI设计全新反应类型"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["INF-010","LIF-008"],"sources":[{"text":"Nature 2024 AI Chemistry","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"CHE-008","domain":"化学","subdomain":"理论化学","title":"化学中的机器学习势函数","description":"用ML模型替代量子化学计算来描述分子间相互作用力，实现大尺度分子动力学模拟。","current_state":"NequIP/Allegro/MACE等等变神经网络势函数精度接近CCSD(T)；2024年通用大模型势函数(UiP/UMA)出现；在蛋白质模拟/材料发现中展示巨大潜力。","key_directions":["通用ML势函数(跨元素/跨体系)","活性学习与在线训练","ML势函数的物理可解释性","与第一性原理的无缝耦合(QM/MM)"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["CHE-004","INF-010"],"sources":[{"text":"Nature 2024 ML Potential","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-001","domain":"社会科学与认知","subdomain":"认知科学","title":"语言起源与演化","description":"人类语言何时、如何从动物交流系统中演化而来?语言能力的生物学基础是什么?","current_state":"FOXP2基因的角色被修正(非'语言基因')；AI语言模型与人类语言习得的对比研究兴起；2024年有研究用AI分析原始语言的可学习性。尼安德特人语言能力仍无定论。","key_directions":["语言习得的计算模型(LLM vs 婴儿)","语言的生物学基础(基因组/神经)","手势vs发声作为语言起源","语言多样性的演化动力学"],"impact":4,"difficulty":4,"timeline":"10-30年","related":["SOC-002","LIF-001"],"sources":[{"text":"Nature Human Behaviour 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-002","domain":"社会科学与认知","subdomain":"认知科学","title":"人类合作与社会复杂性演化","description":"人类社会如何从小规模亲缘群体演化为大规模合作社会?合作的演化机制是什么?","current_state":"文化群体选择理论有实验和模型支持；2024年有跨文化实验验证惩罚/声誉在维持合作中的角色；但大规模合作的涌现机制(制度/文化/技术)仍缺统一理论。","key_directions":["文化演化与基因-文化协同演化","制度演化的博弈论模型","大规模合作的神经基础","AI社会模拟与多智能体系统"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["SOC-001","SOC-003"],"sources":[{"text":"Science 2024 Cooperation","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-003","domain":"社会科学与认知","subdomain":"经济科学","title":"经济物理学与市场复杂性","description":"用物理学和复杂性科学的方法研究经济系统的宏观行为和金融危机。","current_state":"Agent-based模型在经济模拟中成熟；2024年AI多智能体经济模拟(如Stanford smallville)展示涌现行为；但与真实经济数据的校准和预测能力仍弱。","key_directions":["大规模Agent-based经济模拟","金融危机的早期预警系统","不平等的网络动力学","AI驱动的经济政策模拟"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["SOC-002"],"sources":[{"text":"Nature Computational Science 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-004","domain":"社会科学与认知","subdomain":"认知科学","title":"创造力与直觉的计算模型","description":"人类创造力和直觉的本质是什么?能否用AI模拟甚至超越人类创造力?","current_state":"生成式AI在艺术/音乐/写作中展示创造力但争议其'真正'创造性；AI在数学发现(AlphaProof)中展示类直觉能力；但创造力的认知和神经机制仍不清晰。","key_directions":["创造力的认知和神经机制","AI创造力的评估标准","人机协作创造的新模式","直觉与显式推理的互补"],"impact":3,"difficulty":4,"timeline":"10-20年","related":["MAT-006","SOC-001"],"sources":[{"text":"Trends in Cognitive Sciences 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-005","domain":"社会科学与认知","subdomain":"社会网络","title":"信息传播与社会极化","description":"社交媒体如何影响信息传播、观点极化和社会稳定?如何量化并干预极化过程?","current_state":"回音室/过滤气泡效应有实证支持但比预期弱；算法推荐对极化的因果效应2024年有大规模实验证据；但社交媒体与政治极化的因果关系仍是方法论挑战。","key_directions":["算法推荐与信息茧房的因果效应","极化的网络传播模型与干预","虚假信息的传播动力学与遏制","AI生成内容对社会信任的影响"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["INF-006","SOC-003"],"sources":[{"text":"Science 2024 Polarization","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-006","domain":"社会科学与认知","subdomain":"认知科学","title":"意识的自我与自由意志","description":"自我的意识体验是否有神经基础?自由意志是真实的还是幻觉?这些问题在神经科学和哲学中持续争论。","current_state":"Libet实验的'自由意志幻觉'解释被重新审视；2024年有研究显示决策前的准备电位可能有多种解释；自我意识的神经相关(默认模式网络)有新发现。","key_directions":["自由意志的神经科学检验","自我意识的神经基础(默认模式网络)","无意识决策vs有意识决策","AI是否能有自我意识?"],"impact":4,"difficulty":5,"timeline":"未知","related":["LIF-001","SOC-001"],"sources":[{"text":"Nature Neuroscience 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SOC-007","domain":"社会科学与认知","subdomain":"社会网络","title":"AI社会的治理与制度设计","description":"当AI深度嵌入社会系统(司法/医疗/金融/军事)，如何设计制度确保公平/问责/民主?","current_state":"AI在司法判决/信用评估/招聘中的偏见问题被广泛记录；算法审计方法论发展；但AI系统的社会影响评估框架仍不成熟。","key_directions":["AI决策的公平性定义与测量","算法审计方法论","AI嵌入的社会制度设计","人机协作决策的最优分工"],"impact":4,"difficulty":4,"timeline":"5-15年","related":["INF-007","SOC-005"],"sources":[{"text":"AI Now Institute 2024","url":"","type":"official"}],"last_updated":"2026-07"},{"id":"SOC-008","domain":"社会科学与认知","subdomain":"认知科学","title":"费米悖论的社会学维度","description":"从社会学/经济学角度解释大沉默：文明是否因内部因素(资源/核战/AI/气候)而自我毁灭?","current_state":"大过滤器假说和文明自毁假说有多种表述但不可直接检验；AI存在风险(x-risk)的讨论升温； Drake方程的各因子不确定性仍然极大。","key_directions":["大过滤器的位置(过去vs未来)","文明自毁的概率模型","AI x-risk对费米悖论的影响","技术文明的可持续性判据"],"impact":4,"difficulty":5,"timeline":"未知","related":["COS-005","INF-001"],"sources":[{"text":"Fermi Paradox 2024 Review","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SPA-001","domain":"航天与太空探索","subdomain":"推进技术","title":"星际推进技术","description":"实现星际旅行的推进方案：从激光帆到核聚变推进到反物质推进。","current_state":"Breakthrough Starshot(激光帆)概念推进中，但光帆材料和加速器工程仍远未成熟；核聚变推进(Direct Fusion Drive)有概念设计；NASA Heliotropic太阳帆有进展。","key_directions":["激光帆的材料(石墨烯/超材料)与稳定性","核聚变直接推进(DFD)","核电推进(NTP)的工程验证","反物质推进的产量与存储"],"impact":5,"difficulty":5,"timeline":"30-50年","related":["SPA-002","PHY-007"],"sources":[{"text":"Breakthrough Starshot 2024","url":"https://breakthroughinitiatives.org/initiative/3","type":"official"},{"text":"NASA NIAC 2024","url":"https://www.nasa.gov/niac/","type":"official"}],"last_updated":"2026-07"},{"id":"SPA-002","domain":"航天与太空探索","subdomain":"太空资源","title":"太空资源利用与小行星采矿","description":"从近地小行星和月球上开采水/金属/氦-3等资源，支撑太空经济。","current_state":"OSIRIS-REx和Bennu样本返回(2023)分析矿物成分；NASA Artemis计划推进月球极区水冰开采；但太空采矿的经济可行性和法律框架(外层空间条约)远未解决。","key_directions":["月球水冰的开采与利用(推进剂)","小行星矿物成分的遥感识别","微重力下的采矿与选矿技术","太空资源利用的国际法框架"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["SPA-001","SPA-003"],"sources":[{"text":"NASA Artemis 2024","url":"","type":"official"},{"text":"OSIRIS-REx 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SPA-003","domain":"航天与太空探索","subdomain":"太空安全","title":"行星防御与近地天体撞击","description":"发现并偏转可能撞击地球的近地小行星/彗星，保护地球文明。","current_state":"DART(2022)成功改变小行星Dimorphos轨道；NEOWISE/NEO Surveyor推进近地天体编目；但长周期彗星和来自太阳方向的威胁难以提前发现。","key_directions":["NEO Surveyor空间红外望远镜","小行星偏转技术(动能/引力/核爆)","长周期彗星的发现与追踪","行星防御的国际协调机制"],"impact":4,"difficulty":3,"timeline":"5-15年","related":["SPA-002"],"sources":[{"text":"NASA DART 2024","url":"","type":"official"},{"text":"ESA Hera 2024","url":"","type":"official"}],"last_updated":"2026-07"},{"id":"SPA-004","domain":"航天与太空探索","subdomain":"行星科学","title":"火星生命与宜居性","description":"火星是否曾有(或有)生命?火星的宜居环境和生命信号是什么?","current_state":"Perseverance火星车在Jezero陨石坑发现古代有机分子和可能生物特征;Mars Sample Return计划推迟但样本价值极高;地下雷达探测到液水湖(争议)。","key_directions":["Mars Sample Return(火星样本返回)","火星地下环境的钻探与生命搜索","火星甲烷的来源(生物vs地质)","火星地球化的可行性与伦理"],"impact":5,"difficulty":4,"timeline":"10-20年","related":["LIF-004","COS-004"],"sources":[{"text":"NASA Perseverance 2024","url":"https://science.nasa.gov/mission/mars-2020-perseverance/","type":"official"},{"text":"ESA ExoMars 2024","url":"https://www.esa.int/Science_Exploration/Human_and_Robotic_Exploration/Exploration/ExoMars","type":"official"}],"last_updated":"2026-07"},{"id":"SPA-005","domain":"航天与太空探索","subdomain":"太空生物","title":"太空长期生存与微重力健康","description":"人类在微重力/辐射环境下长期生存的医学挑战：骨密度/肌肉/视力/免疫/辐射防护。","current_state":"国际空间站长期任务数据丰富;双胞胎研究揭示太空飞行的表观遗传效应;NASA模拟火星任务(CHAPEA)进行中;但前往火星的辐射防护和人工重力方案仍未解决。","key_directions":["深空辐射防护(屏蔽/药物)","人工重力(旋转空间站)的健康效果","微重力下的药物代谢与给药","太空生殖与发育的可行性"],"impact":4,"difficulty":4,"timeline":"10-20年","related":["SPA-001","SPA-004"],"sources":[{"text":"NASA CHAPEA 2024","url":"","type":"official"},{"text":"Nature Space Biology 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SPA-006","domain":"航天与太空探索","subdomain":"行星科学","title":"木卫二/土卫二地下海洋探测","description":"木卫二(Europa)和土卫二(Enceladus)的冰下液态海洋是太阳系中最可能有生命的地方之一。","current_state":"Europa Clipper(2024发射)将飞掠Europa; Enceladus的羽流分析发现复杂有机物;但穿透冰壳进入地下海洋的技术(钻探机器人)仍极不成熟。","key_directions":["Europa Clipper的冰壳雷达与成分分析","冰壳穿透机器人( melting/cutting probe)","Enceladus羽流样本的精细分析","地下海洋的生命检测实验设计"],"impact":5,"difficulty":5,"timeline":"15-30年","related":["SPA-004","LIF-004"],"sources":[{"text":"NASA Europa Clipper 2024","url":"https://science.nasa.gov/mission/europa-clipper/","type":"official"}],"last_updated":"2026-07"},{"id":"SPA-007","domain":"航天与太空探索","subdomain":"推进技术","title":"可重复使用火箭与太空运输经济","description":"可重复使用火箭大幅降低发射成本，开启太空经济新时代。","current_state":"SpaceX Falcon 9重复使用成熟;Starship试飞进展(2024-2025);中国可重复使用火箭(朱雀三号/引力一号)研发中;发射成本可能降至$100/kg以下。","key_directions":["Starship完全可重复使用与轨道加注","太空制造与太空太阳能","超大规模星座(Starlink/中国星网)的运营","太空旅游的安全性与规模化"],"impact":4,"difficulty":3,"timeline":"5-10年","related":["SPA-001","SPA-002"],"sources":[{"text":"SpaceX Starship 2025","url":"","type":"paper"},{"text":"FAA Space 2024","url":"","type":"paper"}],"last_updated":"2026-07"},{"id":"SPA-008","domain":"航天与太空探索","subdomain":"太空安全","title":"太空碎片治理与太空交通管理","description":"近地轨道碎片日益增多(凯斯勒效应风险)，需要国际协调的太空交通管理和碎片清除。","current_state":"LEO卫星数量激增(Starlink>6000);凯斯勒效应风险在特定轨道高度上升;主动碎片清除(ADR)技术验证(ELSA-d等);但国际法律框架和责任机制远未建立。","key_directions":["主动碎片清除技术(网/爪/电动力绳)","太空交通管理(避碰自动化)","卫星寿命后处理法规","凯斯勒效应的临界条件预测"],"impact":3,"difficulty":3,"timeline":"5-10年","related":["SPA-007"],"sources":[{"text":"ESA Space Debris 2024","url":"","type":"official"}],"last_updated":"2026-07"}];